import * as fs from "fs";
import * as os from "os";
import * as path from "path";

const Dirty = require("../../../../../../../../../../subject_repositories/node-dirty/lib/dirty/dirty.js");

describe("Dirty database load", () => {
  it("preserves UTF-8 characters that span read stream chunks", async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "dirty-utf8-"));
    const file = path.join(dir, "db");
    const prefix = '{"key":"k","val":"';
    const suffix = '"}\n';
    const padLength = 65535 - prefix.length;
    const expectedValue = "a".repeat(padLength) + "€" + "b".repeat(100);
    fs.writeFileSync(file, prefix + expectedValue + suffix, "utf8");

    const db = new Dirty(file);

    try {
      await new Promise<void>((resolve, reject) => {
        db.once("load", () => resolve());
        db.once("error", (err: Error) => reject(err));
      });

      expect(db.get("k")).toBe(expectedValue);
    } finally {
      await new Promise<void>((resolve) => {
        db.once("write_close", () => resolve());
        db.close();
      });
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
});
